$json$::jsonb) as x(w text, c text, m text, d integer)
), resolved as (
  select gw.id as game_world_id, s.c as club_name, s.m as manager_name, s.d as division
  from source s join public.game_worlds gw on gw.slug = s.w
)
insert into public.game_world_clubs(game_world_id, club_name, club_key, current_manager_name, manager_key, occupied, division, active)
select game_world_id, club_name, public.normal_registration_key(club_name), manager_name,
       case when manager_name is null then null else public.normal_registration_key(manager_name) end,
       manager_name is not null, division, true
from resolved
on conflict (game_world_id, club_key) do update set
  club_name = excluded.club_name,
  current_manager_name = excluded.current_manager_name,
  manager_key = excluded.manager_key,
  occupied = excluded.occupied,
  division = coalesce(excluded.division, public.game_world_clubs.division),
  active = true,
  updated_at = now();
